using RaceDay.Api.Models;
using RaceDay.Api.Services;

namespace RaceDay.Api.Data;

/// <summary>
/// Seeds the same demo data as the Part 1 SQL script, but with real PBKDF2 hashes generated by the API
/// (the Part 1 script used REPLACE_WITH_API_HASH placeholders). Runs only when the Users table is empty.
/// </summary>
public static class DbSeeder
{
    /// <summary>Demo password for all four seeded accounts. Change it before any real deployment.</summary>
    public const string DemoPassword = "RaceDay@2026";

    public static void Seed(RaceDayDbContext db, IPasswordHasher hasher)
    {
        if (db.Users.Any()) return;

        var now = DateTime.UtcNow;
        User NewUser(string first, string last, string email, string role, string phone) => new()
        {
            FirstName = first, LastName = last, Email = email, Role = role, Phone = phone,
            PasswordHash = hasher.Hash(DemoPassword), CreatedAt = now
        };

        var thandi = NewUser("Thandi", "Mokoena", "thandi.organiser@raceday.example", Roles.Organiser, "0825550101");
        var lebo = NewUser("Lebo", "Naidoo", "lebo.organiser@raceday.example", Roles.Organiser, "0825550102");
        var aiden = NewUser("Aiden", "Jacobs", "aiden.participant@raceday.example", Roles.Participant, "0825550103");
        var nandi = NewUser("Nandi", "Dlamini", "nandi.participant@raceday.example", Roles.Participant, "0825550104");

        var senior10K = new Category { Name = "Senior 10K", CategoryType = CategoryTypes.Age, MinimumAge = 20, MaximumAge = 39, DistanceKm = 10, EntryFee = 150 };
        var masters10K = new Category { Name = "Masters 10K", CategoryType = CategoryTypes.Age, MinimumAge = 40, MaximumAge = 99, DistanceKm = 10, EntryFee = 150 };
        var openWalk = new Category { Name = "Open Walk", CategoryType = CategoryTypes.Distance, DistanceKm = 7.5m, EntryFee = 80 };
        var familyWalk = new Category { Name = "Family Walk", CategoryType = CategoryTypes.Distance, DistanceKm = 3, EntryFee = 50 };
        var classic42K = new Category { Name = "Classic 42K", CategoryType = CategoryTypes.Distance, DistanceKm = 42, EntryFee = 450 };
        var novice20K = new Category { Name = "Novice 20K", CategoryType = CategoryTypes.Distance, DistanceKm = 20, EntryFee = 280 };

        var goldenHour = new Event
        {
            Organiser = thandi, Name = "Golden Hour 10K", Description = "Sunset road race through Johannesburg South",
            EventDate = new DateTime(2026, 9, 12, 17, 30, 0), Location = "Johannesburg South", DistanceKm = 10,
            EventType = EventTypes.Run, CreatedAt = now, Categories = { senior10K, masters10K },
            WeatherSnapshots = { new WeatherSnapshot { ObservedAt = new DateTime(2026, 9, 12, 12, 0, 0), TemperatureC = 22.5m, Conditions = "Clear skies", WindKph = 12, RainChancePercent = 5 } },
            RoutePoints = { new RoutePoint { SequenceNo = 1, Latitude = -26.204103m, Longitude = 28.047305m, ElevationMetres = 1650 },
                            new RoutePoint { SequenceNo = 2, Latitude = -26.210000m, Longitude = 28.060000m, ElevationMetres = 1668 } }
        };
        var umgeni = new Event
        {
            Organiser = thandi, Name = "Umgeni River Walk", Description = "Accessible community walk with river views",
            EventDate = new DateTime(2026, 9, 27, 7, 0, 0), Location = "Durban North", DistanceKm = 7.5m,
            EventType = EventTypes.Walk, CreatedAt = now, Categories = { openWalk, familyWalk },
            WeatherSnapshots = { new WeatherSnapshot { ObservedAt = new DateTime(2026, 9, 27, 5, 0, 0), TemperatureC = 19, Conditions = "Partly cloudy", WindKph = 9, RainChancePercent = 20 } },
            RoutePoints = { new RoutePoint { SequenceNo = 1, Latitude = -29.770000m, Longitude = 31.050000m, ElevationMetres = 12 },
                            new RoutePoint { SequenceNo = 2, Latitude = -29.760000m, Longitude = 31.060000m, ElevationMetres = 18 } }
        };
        var capeClassic = new Event
        {
            Organiser = lebo, Name = "Cape Peninsula Cycle Classic", Description = "Coastal cycle route for club riders",
            EventDate = new DateTime(2026, 10, 18, 6, 0, 0), Location = "Cape Town", DistanceKm = 42,
            EventType = EventTypes.Cycle, CreatedAt = now, Categories = { classic42K, novice20K },
            WeatherSnapshots = { new WeatherSnapshot { ObservedAt = new DateTime(2026, 10, 18, 4, 0, 0), TemperatureC = 16.5m, Conditions = "Light coastal wind", WindKph = 18, RainChancePercent = 10 } },
            RoutePoints = { new RoutePoint { SequenceNo = 1, Latitude = -33.924900m, Longitude = 18.424100m, ElevationMetres = 8 },
                            new RoutePoint { SequenceNo = 2, Latitude = -34.020000m, Longitude = 18.350000m, ElevationMetres = 115 } }
        };

        var aidenGolden = new Enrolment { Participant = aiden, Event = goldenHour, Category = senior10K, Status = EnrolmentStatuses.Confirmed, EnrolledAt = now };
        var nandiGolden = new Enrolment { Participant = nandi, Event = goldenHour, Category = senior10K, Status = EnrolmentStatuses.Confirmed, EnrolledAt = now };
        var aidenUmgeni = new Enrolment { Participant = aiden, Event = umgeni, Category = openWalk, Status = EnrolmentStatuses.Pending, EnrolledAt = now };
        var nandiCape = new Enrolment { Participant = nandi, Event = capeClassic, Category = classic42K, Status = EnrolmentStatuses.Confirmed, EnrolledAt = now };

        db.AddRange(thandi, lebo, aiden, nandi);
        db.AddRange(goldenHour, umgeni, capeClassic);
        db.AddRange(aidenGolden, nandiGolden, aidenUmgeni, nandiCape);
        db.AddRange(
            new Result { Enrolment = aidenGolden, FinishTime = new TimeSpan(0, 48, 22), Position = 47 },
            new Result { Enrolment = nandiGolden, FinishTime = new TimeSpan(0, 52, 10), Position = 83 });
        db.SaveChanges();
    }
}
